    if (!(autre > 0) || FMT_HEURE.format(autre) !== h || new Date(t).toDateString() !== new Date(autre).toDateString()) return h;
    const a = new Date(t).getTimezoneOffset(), b = new Date(autre).getTimezoneOffset();
