  $('saisie').addEventListener('click', () => { if (!$('compo-mentions').hidden || $('saisie').value.indexOf('@') >= 0) majMentions(); });
  $('saisie').addEventListener('blur', () => setTimeout(() => { if (document.activeElement !== $('saisie')) fermerMentions(); }, 150));
