  async function verifierVersion(force) {
    if (!CAP.miseAJour || !EMPREINTE.test(OPMSG_BUILD) || typeof source.versionServie !== 'function' || maj.enCours) return;
    const t = Date.now();
    if (!force && t - maj.dernier < 20000) return;
    maj.dernier = t;
    let r; try { r = await source.versionServie(); } catch (e) { return; }   // pas de réponse : on réessaiera au prochain rendez-vous
    if (!r) return;
    /* ⛔ SOUS LE MINIMUM QUE LA TOUR A POSÉ, PAS DE « PLUS TARD » : la page ne peut plus écrire (le service répond 426), elle se met à jour tout de suite. */
    if (OPMSG_VERSION > 0 && Number.isInteger(r.min) && r.min > OPMSG_VERSION) { majObligatoire(r.min); return; }
    if (!EMPREINTE.test(r.build || '')) return;
    if (r.build === OPMSG_BUILD) { if (majRetour && !maj.retourDit) { maj.retourDit = true; mot('OP MESSAGES est à jour'); } $('maj-bandeau').hidden = true; return; }
    maj.vu = r.build;
    if (majRetour && !maj.retourDit) { maj.retourDit = true; mot('La nouvelle version n\'a pas encore pu s\'installer : réessaie dans un instant'); maj.repousseA = t + 5 * 60000; }
    if (t < maj.repousseA) return;
    $('maj-bandeau').hidden = false;
  }
  /* ⛔ CE QU'ON ÉTAIT EN TRAIN D'ÉCRIRE SURVIT AU RECHARGEMENT (relecture du gardien, 6 octobre 2026) : les brouillons ne vivent qu'en mémoire, et une mise à jour
     recharge la page. La source les range dans le stockage de l'ONGLET juste avant (effacé à sa fermeture, jamais partagé), et les rend — puis les efface — au
     chargement suivant. Un stockage refusé (navigation privée) : on perd le brouillon, comme avant, sans casser la mise à jour. */
  function brouillonsGarder() {
    if (typeof source.garderBrouillons !== 'function') return;
    if (etat.conv) etat.brouillons[etat.conv] = $('saisie').value;
    const b = {}; for (const [k, v] of Object.entries(etat.brouillons)) if (typeof v === 'string' && v.trim()) b[k] = v.slice(0, 20000);
    source.garderBrouillons(b);
  }
