    if (etat.groupe.mode === 'evenement-new' || etat.groupe.mode === 'rdv-new' || etat.groupe.mode === 'evenement') { $('info-corps').innerHTML = ''; rendreFormEvenement(etat.groupe.mode === 'evenement' ? arg : null, etat.groupe.mode === 'rdv-new'); }
    if (etat.groupe.mode === 'decaler') { $('info-corps').innerHTML = ''; rendreDecaler(arg); }
    if (etat.groupe.mode === 'position') rendrePosition();
    if (etat.groupe.mode === 'theme') rendreTheme();
    if (etat.groupe.mode === 'chercher') rendreRecherche();
    if (etat.groupe.mode === 'medias') rendreMedias();
    if (etat.groupe.mode === 'carte-contact') rendreCarteContact();
    if (etat.groupe.mode === 'transferer') rendreTransfert();
    if (etat.groupe.mode === 'sondage-nouveau') rendreSondageNouveau();
    if (etat.groupe.mode === 'sondage-choix') rendreSondageChoix();
    if (etat.groupe.mode === 'sondage-votes') rendreSondageVotes();
