    $('menu-msg').innerHTML = '<p class="menu-question">Me le rappeler</p>' + h + '<button type="button" class="menu-action" data-menu="annuler">Annuler</button>';
    $('menu-msg').querySelector('button').focus({ preventScroll: true });
