      if (l.some(e => { const o = e.source; return o && o.conv === lien.conv && o.seq === lien.seq && !e.fait && Math.abs(e.debut - x.t) <= RAPPEL_PROCHE_MS; })) { mot('Déjà dans ton agenda'); return; }
