    const p = s => String(s || '').replace(/["\\]/g, ''), c = a.closest('[data-case]');
    if (!a.dataset.ag) return a.dataset.jour ? [(a.classList.contains('mjour-plus') ? '.mjour-plus' : '.mjour-num') + '[data-jour="' + p(a.dataset.jour) + '"]'] : null;
