    const cible = F.source, parent = parentDe(etat.route), h = entree();      // (« cible » : lu à travers « F », le générateur croirait à une méthode de la source)
    const aRendre = !!(parent && h && h.n > 0 && h.p && memeRoute(h.p, parent));
