    dit.push(FMT_JOUR_LONG.format(new Date(r.date + 'T12:00:00')) + (r.anSuivant ? ' ' + r.date.slice(0, 4) : '') + (r.heure ? ' à ' + r.heure.replace(':', ' h ') : ''));
