    const quoi = m.photos ? (m.photos.length > 1 ? m.photos.length + ' photos' : 'Photo') : m.vocal ? 'Message vocal · ' + duree(m.vocal.dur) : m.fichier ? 'Fichier « ' + m.fichier.nom + ' »' : m.carteContact ? 'Fiche de ' + m.carteContact.prenom : '';
