    $('rf-debut').addEventListener('input', () => debutDuree('rf'));
    $('rf-debut').addEventListener('change', () => { debutDuree('rf'); synchroFormRepetition(); });
    $('rf-fin').addEventListener('change', () => finDuree('rf'));
