        const F0 = reu.form;
        source.plafondReunion().then((n) => { if (n && reu.form === F0 && $('rf-invites-note')) { F0.plafond = n; noteInvitesForm(); } }, () => { /* pas de plafond lu : rien n'est bloqué ici, le service répond */ });
