  const EMOJI_SALLE = { pouce: '👍', coeur: '❤️', bravo: '👏', rire: '😂' }, NOM_REACTION = { pouce: 'Pouce levé', coeur: 'Cœur', bravo: 'Bravo', rire: 'Rire' };
